  'Ik ga akkoord met de EUPL 1.2-licentie en heb gelezen welke gegevens OciDeck bewaart.':
      'Αποδέχομαι την άδεια EUPL 1.2 και έχω διαβάσει ποια δεδομένα αποθηκεύει το OciDeck.',
  'Lees de volledige licentie': 'Διαβάστε την πλήρη άδεια',
  'OciDeck is vrije software onder de EUPL 1.2-licentie. Voordat je begint, vragen we je de licentie te accepteren. Hieronder lees je ook welke gegevens OciDeck op dit apparaat bewaart en wanneer er iets je apparaat verlaat.':
      'Το OciDeck είναι ελεύθερο λογισμικό υπό την άδεια EUPL 1.2. Πριν ξεκινήσετε, σας ζητάμε να αποδεχτείτε την άδεια. Παρακάτω μπορείτε επίσης να διαβάσετε ποια δεδομένα αποθηκεύει το OciDeck σε αυτή τη συσκευή και πότε κάτι φεύγει από τη συσκευή σας.',
  'OciDeck verzamelt geen statistieken en stuurt uit zichzelf niets naar buiten. Standaard blijft alles op dit apparaat. Gegevens verlaten dit apparaat alleen als jij dat kiest:\n\n•  Nextcloud/WebDAV: verbind je met een server, dan worden je inlognaam en wachtwoord bewaard (het wachtwoord veilig in de sleutelbos van je systeem) en worden de presentaties die je opent of opslaat naar die server verstuurd.\n•  Openen via URL: OciDeck haalt het bestand op van het adres dat je invoert.\n•  Online media (staat standaard uit): indien ingeschakeld laadt OciDeck afbeeldingen en video\'s van de adressen in je dia\'s.\n•  Externe links (zoals de online licentie) openen in je browser.':
      'Το OciDeck δεν συλλέγει στατιστικά και δεν στέλνει τίποτα προς τα έξω από μόνο του. Από προεπιλογή, όλα παραμένουν σε αυτή τη συσκευή. Τα δεδομένα φεύγουν από αυτή τη συσκευή μόνο όταν το επιλέξετε εσείς:\n\n•  Nextcloud/WebDAV: όταν συνδέεστε σε έναν διακομιστή, το όνομα χρήστη και ο κωδικός σας αποθηκεύονται (ο κωδικός με ασφάλεια στην κλειδοθήκη του συστήματός σας) και οι παρουσιάσεις που ανοίγετε ή αποθηκεύετε στέλνονται σε αυτόν τον διακομιστή.\n•  Άνοιγμα μέσω URL: το OciDeck ανακτά το αρχείο από τη διεύθυνση που εισάγετε.\n•  Διαδικτυακά πολυμέσα (απενεργοποιημένα από προεπιλογή): όταν είναι ενεργοποιημένα, το OciDeck φορτώνει εικόνες και βίντεο από τις διευθύνσεις στις διαφάνειές σας.\n•  Εξωτερικοί σύνδεσμοι (όπως η διαδικτυακή άδεια) ανοίγουν στο πρόγραμμα περιήγησής σας.',
  'OciDeck wordt geleverd onder de European Union Public Licence v1.2. Door akkoord te gaan aanvaard je deze licentie. Je mag OciDeck gebruiken, kopiëren, aanpassen en verspreiden onder de voorwaarden van de EUPL 1.2.':
      'Το OciDeck παρέχεται υπό την European Union Public Licence v1.2. Συμφωνώντας, αποδέχεστε αυτή την άδεια. Μπορείτε να χρησιμοποιείτε, να αντιγράφετε, να τροποποιείτε και να διανέμετε το OciDeck υπό τους όρους της EUPL 1.2.',
  'Om te werken en je werk niet te verliezen, bewaart OciDeck gegevens lokaal op dit apparaat:\n\n•  Je instellingen en voorkeuren (taal, mappen, stijl- en weergaveprofielen, recente bestanden).\n•  Je presentatiematerialen: de presentaties die je opslaat, automatische herstelkopieën en bijlagen zoals afbeeldingsbeschrijvingen.\n•  Deze toestemmingskeuze.\n\nJe kunt dit verwijderen door de bestanden te wissen of de instellingen te resetten.':
      'Για να λειτουργεί και για να διατηρεί την εργασία σας ασφαλή, το OciDeck αποθηκεύει δεδομένα τοπικά σε αυτή τη συσκευή:\n\n•  Τις ρυθμίσεις και τις προτιμήσεις σας (γλώσσα, φακέλους, προφίλ στυλ και εμφάνισης, πρόσφατα αρχεία).\n•  Το υλικό των παρουσιάσεών σας: τις παρουσιάσεις που αποθηκεύετε, αυτόματα αντίγραφα ανάκτησης και συνημμένα όπως περιγραφές εικόνων.\n•  Αυτή την επιλογή συγκατάθεσης.\n\nΜπορείτε να τα καταργήσετε διαγράφοντας τα αρχεία ή επαναφέροντας τις ρυθμίσεις.',
  'Volledige licentie online (23 officiële taalversies)':
