  'Aantal en lengte van bullets, woorden, nesting, kolombalans en de dichtheid van quotes, titels, tabellen en code zodat alles leesbaar past.':
      'Αριθμός και μήκος των bullets, λέξεων, ένθεσης, ισορροπίας στηλών και η πυκνότητα παραθέσεων, τίτλων, πινάκων και κώδικα ώστε όλα να χωρούν ευανάγνωστα.',
  'Bodytekst met contrast onder {crit}:1 telt als fout; daarboven tot de AA-norm als waarschuwing.':
      'Κείμενο σώματος με αντίθεση κάτω από {crit}:1 μετράει ως σφάλμα· πάνω από αυτό έως το πρότυπο AA ως προειδοποίηση.',
