  'De tekst van de voetnoot': 'Το κείμενο της υποσημείωσης',
  'Schrijfbreedte': 'Πλάτος γραφής',
  'Paginabreedte': 'Πλάτος σελίδας',
  'Leeskolom': 'Στήλη ανάγνωσης',
  'Ware grootte': 'Πραγματικό μέγεθος',
  'Pagina-einden gelden alleen op paginabreedte.':
      'Οι αλλαγές σελίδας ισχύουν μόνο σε πλάτος σελίδας.',
  'Hoe breed de leeskolom in de visuele modus is. Smal leest rustig, breed gebruikt meer van het scherm. Of je op die kolom, op paginabreedte of op het hele venster schrijft, kies je in de werkbalk.':
      'Πόσο πλατιά είναι η στήλη ανάγνωσης στην οπτική λειτουργία. Στενή διαβάζεται ήρεμα, πλατιά αξιοποιεί περισσότερη οθόνη. Αν γράφετε σε αυτήν τη στήλη, σε πλάτος σελίδας ή σε όλο το παράθυρο, το επιλέγετε στη γραμμή εργαλείων.',
  'De sprong "{doel}" wijst naar een dia die niet meer bestaat; tijdens het presenteren gebeurt er niets. Kies een andere doeldia.':
      'Το άλμα «{doel}» οδηγεί σε διαφάνεια που δεν υπάρχει πλέον· κατά την παρουσίαση δεν συμβαίνει τίποτα. Επιλέξτε άλλη διαφάνεια προορισμού.',
  'In een cirkel': 'Κύκλος',
  'Onder elkaar': 'Λίστα',
  'Categorie': 'Κατηγορία',
  'Categorie toevoegen': 'Προσθήκη κατηγορίας',
  'Categorie opheffen (blokken blijven behouden)':
      'Κατάργηση κατηγορίας (τα μπλοκ διατηρούνται)',
  'Uitleg': 'Επεξήγηση',
  'Een keuzemenu: elk blok springt bij aanklikken naar een andere dia. Typ per blok een label en een uitleg, kies de doeldia en eventueel een afbeelding. Kies de indeling: raster, onder elkaar of in een cirkel. Met categorieën wissel je tijdens het presenteren tussen groepen blokken. Een blok zonder doel is gewone tekst.':
      'Ένα μενού επιλογών: κάθε μπλοκ μεταβαίνει σε άλλη διαφάνεια όταν το πατήσετε. Πληκτρολογήστε μια ετικέτα και μια επεξήγηση για κάθε μπλοκ, επιλέξτε τη διαφάνεια προορισμού και προαιρετικά μια εικόνα. Επιλέξτε τη διάταξη: πλέγμα, λίστα ή κύκλος. Με τις κατηγορίες εναλλάσσεστε μεταξύ ομάδων μπλοκ κατά την παρουσίαση. Ένα μπλοκ χωρίς προορισμό είναι απλό κείμενο.',
  'Alleen een lege dia.': 'Μόνο μια κενή διαφάνεια.',
  'Hoofdstukken op nieuwe pagina': 'Κεφάλαια σε νέα σελίδα',
  'Elk hoofdstuk begint nu op een nieuwe pagina':
      'Κάθε κεφάλαιο ξεκινά τώρα σε νέα σελίδα',
  'Elk hoofdstuk begon al op een nieuwe pagina':
      'Κάθε κεφάλαιο ξεκινούσε ήδη σε νέα σελίδα',
  'Snijtekens': 'Σημάδια κοπής',
  'Alleen in de LaTeX/PDF-export, en alleen met afloop. Vereist het crop-pakket in je TeX-installatie; een browser-afdruk van de HTML-export zet ze niet.':
      'Μόνο στην εξαγωγή LaTeX/PDF και μόνο με διαφυγή. Απαιτεί το πακέτο crop στην εγκατάσταση TeX σας· η εκτύπωση της εξαγωγής HTML από το πρόγραμμα περιήγησης δεν τα προσθέτει.',
  'Deze paginaopmaak staat in dit document':
      'Αυτή η διαμόρφωση σελίδας είναι αποθηκευμένη σε αυτό το έγγραφο',
  'Deze paginaopmaak komt uit je instellingen':
      'Αυτή η διαμόρφωση σελίδας προέρχεται από τις ρυθμίσεις σας',
  'Paginaopmaak': 'Διαμόρφωση σελίδας',
  'De paginamaat en marges staan nu in dit document; wie het opent krijgt dezelfde pagina. Haal ze eruit om je eigen instelling te laten gelden.':
      'Το μέγεθος σελίδας και τα περιθώρια είναι τώρα αποθηκευμένα σε αυτό το έγγραφο· όποιος το ανοίξει βλέπει την ίδια σελίδα. Αφαιρέστε τα για να ισχύσει η δική σας ρύθμιση.',
  'De paginamaat en marges komen nu uit je instellingen, dus bij een ander kan het document anders uitvallen. Zet ze in het document om dat vast te leggen.':
      'Το μέγεθος σελίδας και τα περιθώρια προέρχονται τώρα από τις ρυθμίσεις σας, οπότε σε κάποιον άλλο το έγγραφο μπορεί να φαίνεται διαφορετικό. Αποθηκεύστε τα στο έγγραφο για να τα σταθεροποιήσετε.',
  'Uit het document halen': 'Αφαίρεση από το έγγραφο',
  'In dit document vastleggen': 'Αποθήκευση σε αυτό το έγγραφο',
  'Rij erboven': 'Γραμμή επάνω',
  'Rij eronder': 'Γραμμή κάτω',
  'Rij weghalen': 'Διαγραφή γραμμής',
  'Kolom links': 'Στήλη αριστερά',
  'Kolom rechts': 'Στήλη δεξιά',
  'Kolom weghalen': 'Διαγραφή στήλης',
  'Met afloop wordt de pagina rondom groter dan het gekozen formaat, zodat inkt die tot de rand loopt dóór de snijlijn heen gaat. De afloop geldt voor élke export tot je hem weer op 0 zet. Laat dit op 0 voor gewoon afdrukken.':
      'Με τη διαφυγή η σελίδα γίνεται μεγαλύτερη από το επιλεγμένο μέγεθος σε όλες τις πλευρές, ώστε το μελάνι που φτάνει στην άκρη να περνά πέρα από τη γραμμή κοπής. Η διαφυγή ισχύει για κάθε εξαγωγή μέχρι να την επαναφέρετε στο 0. Αφήστε το στο 0 για κανονική εκτύπωση.',
