  'Laat zien welke findings het langst openstaan als de begindatum bekend is.':
      'Χρησιμοποιεί μόνο αξιόπιστες ημερομηνίες πρώτης παρατήρησης.',
  'Laat zien op welke systemen de meeste en ernstigste findings staan.':
