  'Datum': 'Ημερομηνία',
  'Komma-gescheiden, bijv. OWASP WSTG@4.2':
      'Χωρισμένα με κόμμα, π.χ. OWASP WSTG@4.2',
  'Titel van de presentatie': 'Τίτλος της παρουσίασης',
  'F-03 · SQL-injectie in het loginformulier':
      'F-03 · Ένεση SQL στη φόρμα σύνδεσης',
  'https://app.voorbeeld/login': 'https://app.example/login',
  'Deze afbeelding naar het AI-model sturen?':
      'Αποστολή αυτής της εικόνας στο μοντέλο AI;',
  'De afbeelding gaat ongewijzigd naar': 'Η εικόνα θα σταλεί χωρίς αλλαγές σε',
  'OciDeck lakt niets weg in een afbeelding: gezichten, tekst op een schermafdruk en gegevens in beeld gaan mee.':
      'Το OciDeck δεν αποκρύπτει τίποτα μέσα σε μια εικόνα: πρόσωπα, κείμενο σε στιγμιότυπο οθόνης και ορατά δεδομένα αποστέλλονται μαζί.',
  'De beeldcontrole vond hier een of meer herkenbare gezichten.':
      'Ο έλεγχος εικόνων εντόπισε εδώ ένα ή περισσότερα αναγνωρίσιμα πρόσωπα.',
  'Naast de export komen twee bestanden te staan waarmee een ontvanger de redacties kan natrekken.':
      'Δίπλα στην εξαγωγή δημιουργούνται δύο αρχεία με τα οποία ο παραλήπτης μπορεί να ελέγξει τις αποκρύψεις.',
  'somt op wat er is weggelaten, zonder de waarden zelf. Dit bestand mag met het rapport mee.':
      'απαριθμεί τι παραλείφθηκε, χωρίς τις ίδιες τις τιμές. Αυτό το αρχείο μπορεί να συνοδεύσει την αναφορά.',
  'bevat de sleutels waarmee elke weggelakte waarde is terug te rekenen. Stuur dit bestand niet mee: dan is de redactie ongedaan gemaakt. Bewaar het bij de bron.':
      'περιέχει τα κλειδιά με τα οποία κάθε αποκρυμμένη τιμή μπορεί να υπολογιστεί ξανά. Μην στέλνετε αυτό το αρχείο: τότε η απόκρυψη αναιρείται. Κρατήστε το κοντά στην πηγή.',
  'slides': 'διαφάνειες',
  'Achtergehouden': 'Παρακρατείται',
  'Achtergehouden: strenger geclassificeerd dan de presentatie':
      'Παρακρατείται: ταξινομείται αυστηρότερα από την παρουσίαση',
  '1 slide achtergehouden door haar TLP':
      '1 διαφάνεια παρακρατείται λόγω του TLP της',
  'slides achtergehouden door hun TLP':
      'διαφάνειες παρακρατούνται λόγω του TLP τους',
  'Deze slides gaan niet mee bij presenteren, exporteren of in het pakket. Verhoog het TLP-niveau van de presentatie bij Presentatie-info om ze mee te nemen.':
      'Αυτές οι διαφάνειες δεν συμπεριλαμβάνονται στην παρουσίαση, στην εξαγωγή ούτε στο πακέτο. Αυξήστε το επίπεδο TLP της παρουσίασης στις Πληροφορίες παρουσίασης για να τις συμπεριλάβετε.',
  'Alle slides zijn achtergehouden door hun TLP-classificatie — niets om te tonen.':
      'Όλες οι διαφάνειες παρακρατούνται λόγω της ταξινόμησης TLP τους, οπότε δεν υπάρχει τίποτα να εμφανιστεί.',
  'Alle slides zijn achtergehouden door hun TLP-classificatie — niets om te exporteren.':
      'Όλες οι διαφάνειες παρακρατούνται λόγω της ταξινόμησης TLP τους, οπότε δεν υπάρχει τίποτα να εξαχθεί.',
  'Alle slides zijn overgeslagen of achtergehouden door hun TLP-classificatie — niets om te tonen.':
      'Όλες οι διαφάνειες παραλείπονται ή παρακρατούνται λόγω της ταξινόμησης TLP τους, οπότε δεν υπάρχει τίποτα να εμφανιστεί.',
  'Alle slides zijn overgeslagen of achtergehouden door hun TLP-classificatie — niets om te exporteren.':
      'Όλες οι διαφάνειες παραλείπονται ή παρακρατούνται λόγω της ταξινόμησης TLP τους, οπότε δεν υπάρχει τίποτα να εξαχθεί.',
  'Grafiekcijfers zijn niet opgeslagen — ze staan alleen nog in dit venster:':
      'Οι αριθμοί των γραφημάτων δεν αποθηκεύτηκαν — υπάρχουν πλέον μόνο σε αυτό το παράθυρο:',
  'In de browser is er geen crashherstel: sluit je dit tabblad, dan is niet-opgeslagen werk weg. Sla je presentatie zelf op.':
      'Στο πρόγραμμα περιήγησης δεν υπάρχει ανάκτηση μετά από κατάρρευση: αν κλείσετε αυτήν την καρτέλα, η μη αποθηκευμένη εργασία χάνεται. Αποθηκεύστε μόνοι σας την παρουσίασή σας.',
  '•  De lokale CVE-database (je start de download zelf): OciDeck haalt de bulkgegevens op via api.github.com en het releasebestand waar dat adres naar wijst.':
      '•  Η τοπική βάση δεδομένων CVE (τη λήψη την ξεκινάτε εσείς): το OciDeck ανακτά τα μαζικά δεδομένα μέσω του api.github.com και του αρχείου έκδοσης στο οποίο παραπέμπει η διεύθυνση αυτή.',
  '•  CVE opzoeken (staat standaard uit): staat het aan, dan gaat je zoekterm naar de ingestelde CVE-spiegel en, als die niets vindt, naar de Europese database van ENISA en naar MITRE.':
      '•  Αναζήτηση CVE (απενεργοποιημένη από προεπιλογή): όταν είναι ενεργή, ο όρος αναζήτησής σας πηγαίνει στο ρυθμισμένο κάτοπτρο CVE και, αν αυτό δεν βρει τίποτα, στην ευρωπαϊκή βάση δεδομένων του ENISA και στο MITRE.',
  '•  Een ingesloten YouTube- of Vimeo-video laadt de speler bij die dienst.':
      '•  Ένα ενσωματωμένο βίντεο YouTube ή Vimeo φορτώνει το πρόγραμμα αναπαραγωγής από την υπηρεσία αυτή.',
  '•  In de browser: weigert de browser een adres rechtstreeks op te halen, dan probeert OciDeck het via de server waar de app vandaan komt; dat adres komt dan bij die server terecht.':
      '•  Στο πρόγραμμα περιήγησης: αν το πρόγραμμα περιήγησης αρνηθεί να ανακτήσει απευθείας μια διεύθυνση, το OciDeck δοκιμάζει ξανά μέσω του διακομιστή από τον οποίο προήλθε η εφαρμογή· η διεύθυνση αυτή φτάνει τότε σε εκείνον τον διακομιστή.',
  'Intrekken is niet vastgelegd. Bij de volgende start geldt uw toestemming weer.':
      'Η ανάκληση δεν αποθηκεύτηκε. Στην επόμενη εκκίνηση η συγκατάθεσή σας ισχύει ξανά.',
  'Een tussenkop die een nieuw deel van de presentatie aankondigt. Houd het kort. Voeg via de afbeeldingsbibliotheek een achtergrondbeeld toe.':
      'Μια επικεφαλίδα ενότητας που ανακοινώνει ένα νέο μέρος της παρουσίασης. Κρατήστε την σύντομη. Προσθέστε μια εικόνα φόντου από τη βιβλιοθήκη εικόνων.',
  'Bronnen doorzoeken…': 'Αναζήτηση στις πηγές…',
  'Niet doorzocht': 'Δεν αναζητήθηκε',
  'Deze controle draait niet in de webversie: gezichtsherkenning vergt een systeembibliotheek die de browser niet heeft. Gebruik de desktopversie om afbeeldingen op gezichten na te kijken.':
      'Αυτός ο έλεγχος δεν εκτελείται στην έκδοση web: η ανίχνευση προσώπων χρειάζεται μια βιβλιοθήκη συστήματος που δεν έχει το πρόγραμμα περιήγησης. Χρησιμοποιήστε την έκδοση για υπολογιστή για να ελέγξετε πρόσωπα στις εικόνες.',
  'Het token heeft lees- en schrijfrechten op de repository nodig. Gitea en Forgejo kennen geen server-side zoeken; OciDeck zoekt lokaal.':
      'Το διακριτικό χρειάζεται δικαιώματα ανάγνωσης και εγγραφής στο αποθετήριο. Το Gitea και το Forgejo δεν έχουν αναζήτηση στον διακομιστή· το OciDeck ψάχνει τοπικά.',
  'Het token heeft de repo-scope nodig (of fijnmazig: Contents lezen en schrijven).':
      'Το διακριτικό χρειάζεται το εύρος repo (ή αναλυτικά: Contents ανάγνωση και εγγραφή).',
  'Het token heeft read_repository, write_repository en read_api nodig. Server-side zoeken vereist Advanced- of Exact Search.':
      'Το διακριτικό χρειάζεται read_repository, write_repository και read_api. Η αναζήτηση στον διακομιστή απαιτεί Advanced ή Exact Search.',
  'Snelle server-zoekopdracht — door indexeringsvertraging kan een net gewijzigd deck ontbreken.':
      'Γρήγορη αναζήτηση στον διακομιστή — λόγω καθυστέρησης ευρετηρίασης, μια πρόσφατα τροποποιημένη παρουσίαση μπορεί να λείπει.',
  'Media blijft niet bewaard in een los .md-bestand':
      'Τα πολυμέσα δεν διατηρούνται σε ένα απλό αρχείο .md',
  'Afbeeldingen, video en audio die je in dit tabblad koos, leven alleen in het geheugen. Een los .md-bestand bewaart ze niet — bij heropenen zijn ze weg. Exporteer als .ocideck-pakket om het beeld mee te nemen.':
      'Οι εικόνες, το βίντεο και ο ήχος που επιλέξατε σε αυτήν την καρτέλα υπάρχουν μόνο στη μνήμη. Ένα απλό αρχείο .md δεν τα διατηρεί — θα χαθούν όταν το ανοίξετε ξανά. Εξαγάγετε ως πακέτο .ocideck για να πάρετε μαζί σας τα πολυμέσα.',
  'Media verwijderd om privacyredenen':
      'Τα πολυμέσα αφαιρέθηκαν για λόγους απορρήτου',
  'Afbeeldingen door AI laten taggen?':
      'Να προσθέσει η ΤΝ ετικέτες σε αυτές τις εικόνες;',
  'afbeeldingen gaan naar': 'εικόνες θα σταλούν σε',
  'een model op dit apparaat': 'ένα μοντέλο σε αυτή τη συσκευή',
  'Doorgaan': 'Συνέχεια',
  'Ontdekkingen': 'Ανακαλύψεις',
  'Wat is gevonden': 'Τι βρέθηκε',
  'Soort': 'Είδος',
  'Dagen onopgemerkt': 'Ημέρες απαρατήρητο',
  'Ontdekking toevoegen': 'Προσθήκη ανακάλυψης',
  'Ontdekking verwijderen': 'Αφαίρεση ανακάλυψης',
  'Kop van de slide': 'Επικεφαλίδα διαφάνειας',
  'dagen onopgemerkt': 'ημέρες απαρατήρητο',
  'Nog geen blootstelling ingevuld — de slide toont dan geen kop, alleen de lijst.':
      'Δεν έχει συμπληρωθεί έκθεση ακόμη — η διαφάνεια δεν δείχνει επικεφαλίδα, μόνο τη λίστα.',
  'Zes ontdekkingen is het maximum; wie er meer noemt maakt een bijlage in plaats van een slide.':
      'Έξι ανακαλύψεις είναι το μέγιστο· όποιος αναφέρει περισσότερες φτιάχνει παράρτημα αντί για διαφάνεια.',
  'Laat de dagen leeg als de eerste blootstelling onbekend is; de slide zegt dan "onbekend" in plaats van nul. Een lege eigenaar leest als "geen eigenaar" en valt rood op.':
      'Αφήστε τις ημέρες κενές αν η πρώτη έκθεση είναι άγνωστη· η διαφάνεια λέει τότε "άγνωστο" αντί για μηδέν. Κενός υπεύθυνος διαβάζεται ως "χωρίς υπεύθυνο" και ξεχωρίζει με κόκκινο.',
  'Wat de scan vond dat niemand wist te hebben. Per ontdekking hoe lang die onopgemerkt bereikbaar was en wie hem nu bezit; de langste blootstelling is de kop.':
      'Τι βρήκε η σάρωση που κανείς δεν ήξερε ότι είχε. Ανά ανακάλυψη, πόσο καιρό ήταν προσβάσιμη απαρατήρητη και ποιος είναι τώρα υπεύθυνος· η μεγαλύτερη έκθεση είναι η επικεφαλίδα.',
  'dag': 'ημέρα',
  'maand': 'μήνας',
  'maanden': 'μήνες',
  'eigenaar': 'υπεύθυνος',
  'langst onopgemerkt bereikbaar': 'περισσότερο προσβάσιμο απαρατήρητο',
  'onbekend': 'άγνωστο',
  'onopgemerkt': 'απαρατήρητο',
  'ontdekking': 'ανακάλυψη',
  'ontdekkingen': 'ανακαλύψεις',
  'Norm en prestatie': 'Στόχος και επίδοση',
  'Norm per rij (optioneel)': 'Στόχος ανά γραμμή (προαιρετικό)',
  'Bandgrenzen (optioneel)': 'Όρια ζωνών (προαιρετικό)',
  'Open bevindingen': 'Ανοιχτά ευρήματα',
  'dagen': 'ημέρες',
  'was': 'ήταν',
  'Cijfers': 'Αριθμοί',
  'Cijfer': 'Αριθμός',
  'Niet alles kon worden hersteld. Wat onleesbaar was, is bewaard gebleven.':
      'Δεν ήταν δυνατή η επαναφορά όλων. Ό,τι δεν ήταν αναγνώσιμο διατηρήθηκε.',
  'Verdieping': 'Εμβάθυνση',
  'Hoeveel detail?': 'Πόση λεπτομέρεια;',
  'Met verdieping': 'Με εμβάθυνση',
  'Beknopt': 'Συνοπτικό',
  'Het detail achter het verhaal. Deze slide gaat mee in de volledige export en valt weg in de beknopte — los van wie hem mag zien.':
      'Η λεπτομέρεια πίσω από την ιστορία. Αυτή η διαφάνεια ταξιδεύει με την πλήρη εξαγωγή και λείπει από τη συνοπτική — ανεξάρτητα από το ποιος μπορεί να τη δει.',
  'Bekijk de foto op ware grootte': 'Δείτε τη φωτογραφία σε πλήρες μέγεθος',
  'Azure-sleutel of SAS-token': 'κλειδί Azure ή διακριτικό SAS',
  'wachtwoordhash': 'σύνοψη κωδικού πρόσβασης',
  'TOTP-seed (tweede factor)': 'σπόρος TOTP (δεύτερος παράγοντας)',
  'mogelijk een sleutel of wachtwoord': 'πιθανώς κλειδί ή κωδικός πρόσβασης',
  'oud btw-nummer (bevat een BSN)': 'παλιός ΑΦΜ (περιέχει προσωπικό αριθμό)',
  'vreemdelingennummer (V-nummer)': 'αριθμός αλλοδαπού (αριθμός V)',
  'administratienummer (A-nummer)': 'διοικητικός αριθμός (αριθμός A)',
  'BIG-nummer van een zorgverlener':
      'αριθμός μητρώου επαγγελματία υγείας (BIG)',
  'AGB-code': 'κωδικός παρόχου υγείας (AGB)',
  'proces-verbaalnummer': 'αριθμός αστυνομικής έκθεσης',
  'Openen uit…': 'Άνοιγμα από…',
  'Opslaan naar…': 'Αποθήκευση σε…',
  'Stel eerst een verbinding in bij Instellingen → Opslag.':
      'Ρυθμίστε πρώτα μια σύνδεση στις Ρυθμίσεις → Αποθήκευση.',
  'Verlopen datums markeren': 'Επισήμανση ληγμένων ημερομηνιών',
  'Datums gemarkeerd': 'Ημερομηνίες επισημασμένες',
  'Kleurt een cel met een datum van vóór vandaag rood. OciDeck kijkt naar de dag waarop u presenteert, dus een deck dat maanden later terugkomt markeert zichzelf. Alleen jjjj-mm-dd telt als datum. Staat standaard uit.':
      'Χρωματίζει κόκκινο ένα κελί με ημερομηνία πριν από σήμερα. Το OciDeck λαμβάνει υπόψη την ημέρα που παρουσιάζετε, οπότε μια παρουσίαση που επανέρχεται μήνες αργότερα επισημαίνεται μόνη της. Μόνο το εεεε-μμ-ηη μετρά ως ημερομηνία. Απενεργοποιημένο εξ ορισμού.',
  'Standaarden en methodieken': 'Πρότυπα και μεθοδολογίες',
  'Aanvalsoppervlak': 'Επιφάνεια επίθεσης',
  'Soort toevoegen': 'Προσθήκη είδους',
  'Soort verwijderen': 'Αφαίρεση είδους',
  'Soort object': 'Είδος αντικειμένου',
  'Gevonden': 'Βρέθηκαν',
  'Kost werk': 'Θέλει δουλειά',
  'werk': 'δουλειά',
  'nieuw': 'νέα',
  'Geen eigenaar': 'Χωρίς υπεύθυνο',
  'geen eigenaar': 'χωρίς υπεύθυνο',
  'objecten in beeld': 'αντικείμενα σε προβολή',
  'Een overzicht draagt hoogstens acht soorten; meer is een inventarislijst en geen overzicht.':
      'Μια επισκόπηση σηκώνει το πολύ οκτώ είδη· περισσότερα είναι κατάλογος απογραφής, όχι επισκόπηση.',
  'Een deelgetal is groter dan het totaal van zijn soort. De slide toont het zoals ingevuld — controleer de bron.':
      'Ένα μερικό σύνολο ξεπερνά το σύνολο του είδους του. Η διαφάνεια το δείχνει όπως δόθηκε — ελέγξτε την πηγή.',
  'De drie laatste zijn deelverzamelingen van het gevonden aantal; OciDeck telt niets zelf, de cijfers komen uit uw scan.':
      'Τα τρία τελευταία είναι υποσύνολα του αριθμού που βρέθηκε· το OciDeck δεν μετρά τίποτα μόνο του, τα νούμερα έρχονται από τη σάρωσή σας.',
  'Het aanvalsoppervlak per soort object: hoeveel er zijn, hoeveel er werk kosten, wat nieuw is en wat niemand bezit. Dat laatste is meestal het gesprek.':
      'Η επιφάνεια επίθεσης ανά είδος αντικειμένου: πόσα υπάρχουν, πόσα θέλουν δουλειά, τι είναι νέο και τι δεν ανήκει σε κανέναν. Το τελευταίο είναι συνήθως η συζήτηση.',
  'Acties en besluiten': 'Ενέργειες και αποφάσεις',
  'Actie': 'Ενέργεια',
  'Deadline': 'Προθεσμία',
  'Stand': 'Κατάσταση',
  'geen datum': 'χωρίς ημερομηνία',
  'Besluit gevraagd': 'Απαιτείται απόφαση',
  'Escalatie': 'Κλιμάκωση',
  'Open': 'Ανοιχτό',
  'Loopt': 'Σε εξέλιξη',
  'Afgerond': 'Ολοκληρώθηκε',
  'Scorecard': 'Κάρτα δεικτών',
  'Cijfer toevoegen': 'Προσθήκη δείκτη',
  'Cijfer verwijderen': 'Αφαίρεση δείκτη',
  'Richting': 'Κατεύθυνση',
  'ongewijzigd': 'αμετάβλητο',
  'Lager is beter': 'Χαμηλότερο είναι καλύτερο',
  'Hoger is beter': 'Υψηλότερο είναι καλύτερο',
  'Neutraal': 'Ουδέτερο',
  'Nu': 'Τώρα',
  'Vorige rapportage': 'Προηγούμενη αναφορά',
  'Een scorecard toont hoogstens vijf cijfers; meer leest niet meer als een oordeel.':
      'Μια κάρτα δεικτών δείχνει το πολύ πέντε μεγέθη· περισσότερα δεν διαβάζονται πια ως κρίση.',
  'Laat de vorige rapportage leeg als er nog geen meting was; de slide toont dan geen verandering.':
      'Αφήστε την προηγούμενη αναφορά κενή αν δεν υπήρχε ακόμη μέτρηση· η διαφάνεια δεν θα δείξει μεταβολή.',
  'Bepaalt of een stijging groen of rood kleurt. De pijl volgt altijd de cijfers.':
      'Καθορίζει αν μια άνοδος χρωματίζεται πράσινη ή κόκκινη. Το βέλος ακολουθεί πάντα τους αριθμούς.',
  'Een paar kerncijfers met het cijfer van de vorige rapportage ernaast, zodat de verandering het verhaal vertelt. Geef per cijfer aan of stijgen goed of slecht nieuws is.':
      'Λίγα βασικά μεγέθη με το μέγεθος της προηγούμενης αναφοράς δίπλα, ώστε την ιστορία να τη λέει η μεταβολή. Δηλώστε για καθένα αν η άνοδος είναι καλό ή κακό νέο.',
  'Zekere vondsten als fout behandelen':
      'Αντιμετώπιση βέβαιων ευρημάτων ως σφαλμάτων',
  'Normaal is een zekere vondst — een BSN, een IBAN, een e-mailadres — een waarschuwing die je kunt negeren. Aan maakt er een fout van, en dan kan de export erop blokkeren als je die instelling ook aan hebt staan. Bedoeld voor omgevingen waar zulke gegevens er echt niet doorheen mogen. Onzekere vondsten blijven een waarschuwing.':
      'Κανονικά ένα βέβαιο εύρημα — ένας ΑΜΚΑ, ένα IBAN, μια διεύθυνση email — είναι μια προειδοποίηση που μπορείτε να αγνοήσετε. Ενεργό το μετατρέπει σε σφάλμα, και τότε η εξαγωγή μπορεί να μπλοκάρει σε αυτό αν έχετε ενεργή και εκείνη τη ρύθμιση. Προορίζεται για περιβάλλοντα όπου τέτοια δεδομένα πραγματικά δεν πρέπει να περάσουν. Τα αβέβαια ευρήματα παραμένουν προειδοποίηση.',
  'Medicare-nummer — een zorggegeven': 'αριθμός Medicare — δεδομένο υγείας',
  'bedrijfsnummer': 'αριθμός εταιρείας',
  'zorgverzekeringsnummer (RAMQ) — een zorggegeven':
      'αριθμός ασφάλισης υγείας (RAMQ) — δεδομένο υγείας',
  'zorgverzekeringsnummer (OHIP) — een zorggegeven':
      'αριθμός ασφάλισης υγείας (OHIP) — δεδομένο υγείας',
  'bedrijfsnummer (BN)': 'αριθμός επιχείρησης (BN)',
  'zorgverlenersnummer (NPI)': 'αριθμός παρόχου υγείας (NPI)',
  'Medicare-nummer (MBI) — een zorggegeven':
      'αριθμός Medicare (MBI) — δεδομένο υγείας',
  'wacht op verbinding': 'αναμονή σύνδεσης',
  'Opgeslagen op deze computer, nog niet in de repository. Gaat mee zodra er weer verbinding is — of nu, met "Wachtrij legen".':
      'Αποθηκευμένο σε αυτόν τον υπολογιστή, όχι ακόμη στο αποθετήριο. Θα σταλεί μόλις υπάρξει ξανά σύνδεση — ή τώρα, με «Άδειασμα ουράς».',
  'Branch (optioneel)': 'Κλάδος (προαιρετικό)',
  'let op: de standaardbranch is': 'προσοχή: ο προεπιλεγμένος κλάδος είναι',
  'jij werkt op': 'εσύ εργάζεσαι στον',
  'werkgeversnummer (EIN)': 'αριθμός εργοδότη (EIN)',
  'laatste vier cijfers van een SSN': 'τα τέσσερα τελευταία ψηφία ενός SSN',
  'geboortedatum, postcode en geslacht samen — die drie wijzen meestal één persoon aan, ook zonder naam':
      'ημερομηνία γέννησης, ταχυδρομικός κώδικας και φύλο μαζί — αυτά τα τρία συνήθως προσδιορίζουν ένα άτομο, ακόμη και χωρίς όνομα',
  'Het certificaat van deze server wordt niet vertrouwd. Bij een zelf gehoste server kun je het bekijken en vertrouwen bij Instellingen → Opslag.':
      'Το πιστοποιητικό αυτού του διακομιστή δεν είναι έμπιστο. Σε αυτο-φιλοξενούμενο διακομιστή μπορείς να το δεις και να το εμπιστευτείς στις Ρυθμίσεις → Αποθήκευση.',
  'Het certificaat van de forge wordt niet vertrouwd. Bij een zelf gehoste forge kun je het bekijken en vertrouwen bij Instellingen → Opslag.':
      'Το πιστοποιητικό αυτού του forge δεν είναι έμπιστο. Σε αυτο-φιλοξενούμενο forge μπορείς να το δεις και να το εμπιστευτείς στις Ρυθμίσεις → Αποθήκευση.',
  'Het certificaat van het endpoint wordt niet vertrouwd. Bij een zelf gehost endpoint kun je het bekijken en vertrouwen bij Instellingen → Opslag.':
      'Το πιστοποιητικό αυτού του τελικού σημείου δεν είναι έμπιστο. Σε αυτο-φιλοξενούμενο τελικού σημείου μπορείς να το δεις και να το εμπιστευτείς στις Ρυθμίσεις → Αποθήκευση.',
  'Het certificaat van de forge wordt niet vertrouwd — zelfondertekend, verlopen, of op een andere naam gesteld.':
      'Το πιστοποιητικό του forge δεν είναι έμπιστο — αυτο-υπογεγραμμένο, ληγμένο ή εκδοθέν σε άλλο όνομα.',
  'Het certificaat van het endpoint wordt niet vertrouwd — zelfondertekend, verlopen, of op een andere naam gesteld.':
      'Το πιστοποιητικό του τελικού σημείου δεν είναι έμπιστο — αυτο-υπογεγραμμένο, ληγμένο ή εκδοθέν σε άλλο όνομα.',
  'creditcardnummer': 'αριθμός πιστωτικής κάρτας',
  'beveiligingscode van een creditcard': 'κωδικός ασφαλείας κάρτας (CVV)',
  'gegevens in de sprekersnotities — onzichtbaar op de slide, wél in de export':
      'δεδομένα στις σημειώσεις ομιλητή — αόρατα στη διαφάνεια, αλλά εξάγονται',
  'Certificaat vertrouwen?': 'Εμπιστοσύνη σε αυτό το πιστοποιητικό;',
  'Het certificaat van deze server is niet ondertekend door een erkende uitgever. Dat is gewoon bij een zelf gehoste server, maar het is ook hoe een afgeluisterde verbinding eruitziet.':
      'Το πιστοποιητικό αυτού του διακομιστή δεν έχει υπογραφεί από αναγνωρισμένο εκδότη. Αυτό είναι φυσιολογικό σε αυτο-φιλοξενούμενο διακομιστή, αλλά έτσι φαίνεται και μια υποκλαπείσα σύνδεση.',
  'Vergelijk de vingerafdruk hieronder met wat je server zelf toont. Komen ze overeen, dan praat je met de juiste machine.':
      'Σύγκρινε το αποτύπωμα παρακάτω με αυτό που δείχνει ο ίδιος ο διακομιστής σου. Αν ταιριάζουν, μιλάς με τη σωστή μηχανή.',
  'Uitgegeven aan': 'Εκδόθηκε για',
  'Uitgegeven door': 'Εκδόθηκε από',
  'Geldig tot': 'Ισχύει έως',
  'Vingerafdruk (SHA-256)': 'Αποτύπωμα (SHA-256)',
  'Alleen dit ene certificaat wordt vertrouwd. Vervangt de server het later, dan vraagt OciDeck het opnieuw.':
      'Μόνο αυτό το πιστοποιητικό γίνεται έμπιστο. Αν ο διακομιστής το αντικαταστήσει αργότερα, το OciDeck θα ρωτήσει ξανά.',
  'Vertrouwen': 'Εμπιστεύομαι',
  'Certificaat bekijken': 'Προβολή πιστοποιητικού',
  'De plekken waar je presentaties bewaart en doorzoekt — mappen op deze computer, WebDAV-servers, S3-buckets en git-repositories door elkaar. Sleep ze in de volgorde die jij wilt: de bovenste van een soort geldt als standaard.':
      'Τα μέρη όπου κρατάς και αναζητάς τις παρουσιάσεις σου — φάκελοι σε αυτόν τον υπολογιστή, διακομιστές WebDAV, κάδοι S3 και αποθετήρια git ανακατεμένα. Σύρε τα στη σειρά που θέλεις: το πρώτο κάθε είδους μετράει ως προεπιλογή.',
  '•  S3-opslag: verbind je met een bucket, dan worden het endpoint, de bucketnaam en je toegangssleutel bewaard (de geheime sleutel veilig in de sleutelbos van je systeem) en worden de presentaties die je opent of opslaat naar die opslagdienst verstuurd.':
      '•  Αποθήκευση S3: όταν συνδέεσαι σε έναν κάδο, αποθηκεύονται το endpoint, το όνομα του κάδου και το κλειδί πρόσβασής σου (το μυστικό κλειδί με ασφάλεια στην κλειδοθήκη του συστήματός σου) και οι παρουσιάσεις που ανοίγεις ή αποθηκεύεις στέλνονται σε αυτήν την υπηρεσία αποθήκευσης.',
  '•  Git-opslag: verbind je met een repository, dan wordt je toegangstoken bewaard (veilig in de sleutelbos van je systeem) en worden de presentaties die je opslaat als commits naar die server verstuurd. Een werkkopie van de repository blijft onversleuteld op dit apparaat staan.':
      '•  Αποθήκευση Git: όταν συνδέεσαι σε ένα αποθετήριο, αποθηκεύεται το διακριτικό πρόσβασής σου (με ασφάλεια στην κλειδοθήκη του συστήματός σου) και οι παρουσιάσεις που αποθηκεύεις στέλνονται σε αυτόν τον διακομιστή ως commits. Ένα αντίγραφο εργασίας του αποθετηρίου παραμένει μη κρυπτογραφημένο σε αυτήν τη συσκευή.',
  'Voor de taal van dit deck ontbreken de ziekte- en aandoeningsnamen. Religie, politieke overtuiging en vakbondstermen worden wel herkend, en controlegetallen (BSN, IBAN, paspoort) werken altijd — maar reken er niet op dat een diagnose gevonden wordt.':
      'Για τη γλώσσα αυτής της παρουσίασης λείπουν τα ονόματα ασθενειών. Η θρησκεία, η πολιτική άποψη και οι συνδικαλιστικοί όροι αναγνωρίζονται, και τα μοτίβα με ψηφίο ελέγχου (ΑΜΚΑ, IBAN, διαβατήριο) λειτουργούν πάντα — αλλά μη βασίζεστε στον εντοπισμό διάγνωσης.',
  'niet getest': 'μη δοκιμασμένη',
  'Werkte op': 'Λειτούργησε στις',
  'Je bent aangemeld, maar hebt hier geen toegang. Je wachtwoord is niet het probleem — vraag de beheerder om rechten op deze map.':
      'Έχεις συνδεθεί, αλλά δεν έχεις πρόσβαση εδώ. Ο κωδικός σου δεν είναι το πρόβλημα — ζήτησε από τον διαχειριστή δικαιώματα σε αυτόν τον φάκελο.',
  'Je token is geldig, maar mag dit niet. Geef het meer rechten, of wacht als de forge een limiet oplegt.':
      'Το διακριτικό σου είναι έγκυρο, αλλά δεν επιτρέπεται αυτό. Δώσε του περισσότερα δικαιώματα, ή περίμενε αν το forge επιβάλλει όριο.',
  'Het token is geldig, maar mag dit niet — geef het meer rechten op de repository.':
      'Το διακριτικό είναι έγκυρο, αλλά δεν επιτρέπεται αυτό — δώσε του περισσότερα δικαιώματα στο αποθετήριο.',
  'Aangemeld, maar geen toegang — je wachtwoord is niet het probleem. Vraag rechten op deze map.':
      'Συνδεδεμένος, αλλά χωρίς πρόσβαση — ο κωδικός σου δεν είναι το πρόβλημα. Ζήτησε δικαιώματα σε αυτόν τον φάκελο.',
  'Dit lijkt een volledige DAV-URL. Bij Nextcloud leidt OciDeck dat pad zelf af — hier hoort alleen de server te staan.':
      'Αυτό μοιάζει με πλήρες URL DAV. Στο Nextcloud το OciDeck παράγει μόνο του αυτή τη διαδρομή — εδώ ανήκει μόνο ο διακομιστής.',
  'Overnemen': 'Εφαρμογή',
  'WebDAV is niet (goed) ingesteld — controleer de servergegevens bij Instellingen → Opslag.':
      'Το WebDAV δεν έχει ρυθμιστεί σωστά — ελέγξτε τα στοιχεία διακομιστή στις Ρυθμίσεις → Αποθήκευση.',
  'De git-repository is niet (goed) ingesteld — controleer server, eigenaar en repository bij Instellingen → Opslag.':
      'Το αποθετήριο git δεν έχει ρυθμιστεί σωστά — ελέγξτε διακομιστή, κάτοχο και αποθετήριο στις Ρυθμίσεις → Αποθήκευση.',
  'De servernaam van de forge bestaat niet, of is niet op te zoeken. Controleer de server-URL op een typefout.':
      'Το όνομα διακομιστή του forge δεν υπάρχει ή δεν μπορεί να αναζητηθεί. Ελέγξτε το URL του διακομιστή για τυπογραφικό λάθος.',
  'Deze forge heeft een privé- of LAN-adres. Markeer hem als vertrouwd intern bij Instellingen → Opslag.':
      'Αυτό το forge έχει ιδιωτική διεύθυνση ή διεύθυνση LAN. Σημειώστε το ως έμπιστο εσωτερικό στις Ρυθμίσεις → Αποθήκευση.',
  'De forge is niet bereikbaar — controleer je verbinding en de server-URL.':
      'Το forge δεν είναι προσβάσιμο — ελέγξτε τη σύνδεσή σας και το URL του διακομιστή.',
  'Aanmelden bij de forge mislukt. Controleer je token: het heeft leesrechten op de repository nodig, en schrijfrechten om op te slaan.':
      'Η σύνδεση στο forge απέτυχε. Έλεγξε το διακριτικό: χρειάζεται δικαίωμα ανάγνωσης στο αποθετήριο και εγγραφής για αποθήκευση.',
  'Niet gevonden in de repository — of je token mag het niet zien.':
      'Δεν βρέθηκε στο αποθετήριο — ή το διακριτικό σου δεν επιτρέπεται να το δει.',
  'De forge gaf een fout. Probeer het later opnieuw.':
      'Το forge επέστρεψε σφάλμα. Δοκιμάστε ξανά αργότερα.',
  'Dit adres antwoordt niet als een forge. Klopt de soort forge bij Instellingen → Opslag?':
      'Αυτή η διεύθυνση δεν απαντά σαν forge. Είναι σωστό το είδος forge στις Ρυθμίσεις → Αποθήκευση;',
  'Stel eerst een WebDAV-server in bij Instellingen → Opslag.':
      'Ρυθμίστε πρώτα έναν διακομιστή WebDAV στις Ρυθμίσεις → Αποθήκευση.',
  'Nodig wanneer de forge op een privé- of thuisnetwerk draait. Zonder deze vlag weigert de beveiliging een privé-adres.':
      'Χρειάζεται όταν το forge τρέχει σε ιδιωτικό ή οικιακό δίκτυο. Χωρίς αυτή τη σήμανση ο έλεγχος ασφαλείας απορρίπτει ιδιωτική διεύθυνση.',
  'Vul server-URL, eigenaar en repository in':
      'Συμπληρώστε URL διακομιστή, κάτοχο και αποθετήριο',
  'de standaardbranch heet': 'ο προεπιλεγμένος κλάδος ονομάζεται',
  'die wordt voortaan gebruikt': 'αυτός θα χρησιμοποιείται από εδώ και πέρα',
  'de repository is nog leeg; de eerste opslag vult hem':
      'το αποθετήριο είναι ακόμη κενό· η πρώτη αποθήκευση θα το γεμίσει',
  'let op: dit token mag alleen lezen, dus opslaan zal mislukken':
      'προσοχή: αυτό το διακριτικό μπορεί μόνο να διαβάζει, άρα η αποθήκευση θα αποτύχει',
  'Aanmelden mislukt — controleer het token. Het heeft leesrechten op de repository nodig, en schrijfrechten om te kunnen opslaan.':
      'Η σύνδεση απέτυχε — ελέγξτε το διακριτικό. Χρειάζεται δικαίωμα ανάγνωσης στο αποθετήριο και εγγραφής για να αποθηκεύει.',
  'Repository niet gevonden — of je token mag hem niet zien. Controleer eigenaar en repositorynaam.':
      'Το αποθετήριο δεν βρέθηκε — ή το διακριτικό σου δεν επιτρέπεται να το δει. Έλεγξε τον κάτοχο και το όνομα αποθετηρίου.',
  'Dit adres antwoordt niet als een forge. Klopt de soort forge die je hebt gekozen?':
      'Αυτή η διεύθυνση δεν απαντά σαν forge. Είναι σωστό το είδος forge που επέλεξες;',
  'kenteken': 'αριθμός κυκλοφορίας',
  'Voor de taal van dit deck is er geen trefwoordenlijst voor bijzondere persoonsgegevens. Patronen met een controlegetal (BSN, IBAN, paspoort) werken wel; woorden als "diagnose" of "verdachte" worden niet herkend.':
      'Για τη γλώσσα αυτής της παρουσίασης δεν υπάρχει λίστα λέξεων-κλειδιών για ειδικές κατηγορίες προσωπικών δεδομένων. Τα μοτίβα με ψηφίο ελέγχου (ΑΜΚΑ, IBAN, διαβατήριο) λειτουργούν· λέξεις όπως «διάγνωση» ή «ύποπτος» δεν αναγνωρίζονται.',
  'Landpakketten voor identificatienummers':
      'Πακέτα χωρών για αριθμούς ταυτοποίησης',
  'Nummers als het BSN of het PESEL zijn landgebonden. Heel Europa staat aan omdat de meeste van die nummers een controlegetal hebben: die aanzetten kost vrijwel geen valse meldingen. IBAN, e-mail, geheimen en paspoortstroken staan hier los van en worden altijd nagekeken.':
      'Αριθμοί όπως το ολλανδικό BSN ή το πολωνικό PESEL είναι ανά χώρα. Όλη η Ευρώπη είναι ενεργή επειδή οι περισσότεροι από αυτούς τους αριθμούς έχουν ψηφίο ελέγχου: η ενεργοποίησή τους δεν κοστίζει σχεδόν καθόλου ψευδείς ειδοποιήσεις. IBAN, email, μυστικά και ζώνες διαβατηρίου είναι ανεξάρτητα και ελέγχονται πάντα.',
