  'De privacycontrole': 'Ο έλεγχος απορρήτου',
  'OciDeck leest je dia\'s na op gegevens die privacygevoelig kunnen zijn: identificatienummers, contactgegevens, telefoonnummers, bankrekeningen, sleutels en wachtwoorden, en bijzondere persoonsgegevens. Dat gebeurt volledig op dit apparaat: er wordt niets verstuurd, en de gevonden waarde zelf komt in geen enkele melding te staan.':
      'Το OciDeck διαβάζει τις διαφάνειές σου για δεδομένα που μπορεί να είναι ευαίσθητα: αριθμούς ταυτοποίησης, στοιχεία επικοινωνίας, αριθμούς τηλεφώνου, τραπεζικούς λογαριασμούς, κλειδιά και κωδικούς, και ειδικές κατηγορίες προσωπικών δεδομένων. Όλα γίνονται σε αυτή τη συσκευή: τίποτα δεν αποστέλλεται και η τιμή που βρέθηκε δεν εμφανίζεται σε καμία ειδοποίηση.',
  'De controle garandeert niet dat alles wordt gevonden; ze verkleint de kans dat er persoonsgegevens onbedoeld uitlekken.':
      'Ο έλεγχος δεν εγγυάται ότι θα βρεθούν τα πάντα· μειώνει την πιθανότητα να διαρρεύσουν προσωπικά δεδομένα κατά λάθος.',
  'Tekst in afbeeldingen blijft buiten beeld, gelinkte bestanden worden niet geopend, en gegevens zonder herkenbaar patroon herkent geen enkele scanner. Een dia zonder meldingen is een dia waarin wíj niets hebben gevonden, niet een dia waarvan vaststaat dat er niets in staat. Wat je deelt, blijft jouw beslissing en jouw verantwoordelijkheid.':
      'Το κείμενο μέσα σε εικόνες μένει εκτός εμβέλειας, τα συνδεδεμένα αρχεία δεν ανοίγονται και κανένας σαρωτής δεν αναγνωρίζει δεδομένα χωρίς αναγνωρίσιμο μοτίβο. Μια διαφάνεια χωρίς ευρήματα είναι μια διαφάνεια στην οποία *εμείς* δεν βρήκαμε τίποτα — όχι μια διαφάνεια για την οποία αποδεικνύεται ότι δεν περιέχει τίποτα. Ό,τι μοιράζεσαι παραμένει δική σου απόφαση και δική σου ευθύνη.',
  'telefoonnummer': 'αριθμός τηλεφώνου',
  'Voor wie is deze export?': 'Για ποιον είναι αυτή η εξαγωγή;',
  'Volledig': 'Πλήρες',
  'Geredigeerd': 'Αποκρυμμένο',
  'Voor de opdrachtgever of auditor: alleen wat je zelf op "weglaten" hebt gezet, gaat eruit. De rest blijft leesbaar, zodat een derde partij de bevindingen kan controleren.':
      'Για τον πελάτη ή τον ελεγκτή: αφαιρείται μόνο ό,τι όρισες ως «παράλειψη». Τα υπόλοιπα μένουν αναγνώσιμα, ώστε ένας τρίτος να μπορεί να ελέγξει τα ευρήματα.',
  'Voor de bredere kring: alles wat de controle vindt gaat eruit, ook op slides die je hebt geaccepteerd. Het bestand krijgt "-geredigeerd" in de naam.':
      'Για ευρύτερο κοινό: αφαιρείται ό,τι βρίσκει ο έλεγχος, ακόμη και σε διαφάνειες που αποδέχτηκες. Το αρχείο παίρνει «-geredigeerd» στο όνομα.',
  'tabel met persoonsgegevens (rijen×kolommen)':
      'πίνακας προσωπικών δεδομένων (γραμμές×στήλες)',
  'massa-persoonsgegevens op één slide':
      'μαζικά προσωπικά δεδομένα σε μία διαφάνεια',
  'gebruikerspad met een naam erin': 'διαδρομή χρήστη που περιέχει όνομα',
  'toegangstoken in een link': 'διακριτικό πρόσβασης σε σύνδεσμο',
  'persoonsgegeven in een link': 'προσωπικό δεδομένο σε σύνδεσμο',
  'deellink met ingebakken toegang':
      'σύνδεσμος κοινής χρήσης με ενσωματωμένη πρόσβαση',
  'e-mailadres in een link': 'διεύθυνση email σε σύνδεσμο',
  'ingesloten afbeelding — wij kunnen er niet in kijken':
      'ενσωματωμένη εικόνα — δεν μπορούμε να δούμε μέσα',
  'Je eigen gegevens': 'Τα δικά σου στοιχεία',
  'Eén per regel: je naam, e-mailadres, telefoonnummer of het domein van je organisatie. Wat hier staat wordt niet gemeld en niet geredigeerd — het is de afzender, geen bevinding. Een domein (example.org) dekt elk adres eronder.':
      'Ένα ανά γραμμή: το όνομά σου, η διεύθυνση email, το τηλέφωνο ή ο τομέας του οργανισμού σου. Ό,τι γράφεις εδώ δεν αναφέρεται και δεν αποκρύπτεται — είναι ο αποστολέας, όχι εύρημα. Ένας τομέας (example.org) καλύπτει κάθε διεύθυνση κάτω από αυτόν.',
  'Bij onafgehandelde persoonsgegevens': 'Με ανεπίλυτα προσωπικά δεδομένα',
  'Export afgebroken vanwege privacybevindingen.':
      'Η εξαγωγή ακυρώθηκε λόγω ευρημάτων απορρήτου.',
  'Export blokkeren': 'Αποκλεισμός εξαγωγής',
  'Export geblokkeerd': 'Η εξαγωγή αποκλείστηκε',
  'Export geblokkeerd: er staan persoonsgegevens in dit deck waarvoor nog geen keuze is gemaakt.':
      'Η εξαγωγή αποκλείστηκε: αυτή η παρουσίαση περιέχει προσωπικά δεδομένα για τα οποία δεν έχεις αποφασίσει ακόμη.',
  'Kies per slide wat er moet gebeuren, of exporteer bewust zoals het is.':
      'Επίλεξε ανά διαφάνεια τι θα γίνει, ή εξήγαγε συνειδητά ως έχει.',
  'Maak per slide een keuze (accepteren, waarschuwen of weglaten) voordat je exporteert. Dit is zo ingesteld bij Beveiliging.':
      'Κάνε επιλογή ανά διαφάνεια (αποδοχή, προειδοποίηση ή παράλειψη) πριν την εξαγωγή. Ρυθμίζεται στην Ασφάλεια.',
  'Niets doen': 'Να μη γίνει τίποτα',
  'Persoonsgegevens in dit deck': 'Προσωπικά δεδομένα σε αυτή την παρουσίαση',
  'Verder in dit deck:': 'Αλλού σε αυτή την παρουσίαση:',
  'Waarschuwen vóór export': 'Προειδοποίηση πριν την εξαγωγή',
  'bevinding(en) zonder keuze.': 'εύρημα/-τα χωρίς επιλογή.',
  'geaccepteerd': 'αποδεκτά',
  'geredigeerd': 'αποκρυμμένα',
  'met waarschuwing': 'με προειδοποίηση',
  'Deze regel nooit meer melden': 'Να μην αναφέρεται ξανά αυτός ο κανόνας',
  'politieke opvatting': 'πολιτική άποψη',
  'etnische afkomst': 'εθνοτική καταγωγή',
  'seksuele geaardheid': 'σεξουαλικός προσανατολισμός',
  ' Op deze slide staat ook een identificerend gegeven, dus dit is herleidbaar tot een persoon.':
      ' Σε αυτή τη διαφάνεια υπάρχει και ένα στοιχείο ταυτοποίησης, άρα αυτό ανάγεται σε πρόσωπο.',
  'Bijzonder persoonsgegeven (AVG art. 9/10)':
      'Ειδική κατηγορία προσωπικών δεδομένων (GDPR άρθρο 9/10)',
  'gezondheidsgegeven': 'δεδομένο υγείας',
  'strafrechtelijk gegeven': 'ποινικό δεδομένο',
  'religie of levensovertuiging': 'θρησκεία ή πεποιθήσεις',
  'vakbondslidmaatschap': 'συνδικαλιστική ιδιότητα',
  'biometrisch gegeven': 'βιομετρικό δεδομένο',
  'genetisch gegeven': 'γενετικό δεδομένο',
  'parketnummer': 'αριθμός δικογραφίας',
  'nationaal identificatienummer': 'εθνικός αριθμός ταυτοποίησης',
  'Mogelijk geheim': 'Πιθανό μυστικό',
  'sleutel of token': 'κλειδί ή διακριτικό',
  'private sleutel': 'ιδιωτικό κλειδί',
  'toegangstoken (JWT)': 'διακριτικό πρόσβασης (JWT)',
  'databaseverbinding met wachtwoord': 'σύνδεση βάσης δεδομένων με κωδικό',
  'wachtwoord in klare tekst': 'κωδικός σε απλό κείμενο',
  'Afbreken': 'Ακύρωση',
  'Afgebroken. Er is niets half achtergebleven.':
      'Ακυρώθηκε. Δεν έμεινε τίποτα μισοτελειωμένο.',
  'Bijwerken': 'Ενημέρωση',
  'Binnenhalen…': 'Γίνεται λήψη…',
  'CVE\'s': 'CVE',
  'Database ophalen': 'Λήψη βάσης δεδομένων',
  'De CVE-lijst kon niet worden opgehaald. Controleer je verbinding en probeer het opnieuw; een half binnengehaalde lijst is weggegooid.':
      'Δεν ήταν δυνατή η λήψη της λίστας CVE. Έλεγξε τη σύνδεσή σου και δοκίμασε ξανά· μια μισοκατεβασμένη λίστα απορρίφθηκε.',
  'De nieuwste uitgave opzoeken…': 'Αναζήτηση της πιο πρόσφατης έκδοσης…',
  'Dit is een grote download: ruim 500 MB binnenhalen, tijdelijk zo\'n 1,5 GB schijfruimte, en afhankelijk van je verbinding en apparaat al gauw tien tot dertig minuten werk. Daarna blijft er een index van enkele honderden megabytes staan. Op een verbinding die per megabyte betaalt, doe je dit liever niet.':
      'Πρόκειται για μεγάλη λήψη: πάνω από 500 MB, προσωρινά περίπου 1,5 GB χώρου στον δίσκο και, ανάλογα με τη σύνδεση και τη συσκευή σου, εύκολα δέκα έως τριάντα λεπτά δουλειάς. Μετά παραμένει ένα ευρετήριο μερικών εκατοντάδων megabyte. Σε σύνδεση που χρεώνεται ανά megabyte, καλύτερα να μην το κάνεις.',
  'Er was te weinig schijfruimte. De opbouw vraagt tijdelijk ruim 1,5 GB.':
      'Δεν υπήρχε αρκετός χώρος στον δίσκο. Η δημιουργία χρειάζεται προσωρινά πάνω από 1,5 GB.',
  'Het opgehaalde archief was niet wat we verwachtten en is geweigerd. Er is niets geïnstalleerd.':
      'Το αρχείο που κατέβηκε δεν ήταν αυτό που περιμέναμε και απορρίφθηκε. Δεν εγκαταστάθηκε τίποτα.',
  'Indexeren…': 'Ευρετηρίαση…',
  'Lokaal beschikbaar — opzoeken gebeurt offline, er gaat geen zoekterm naar buiten.':
      'Διαθέσιμο τοπικά — οι αναζητήσεις γίνονται εκτός σύνδεσης, κανένας όρος αναζήτησης δεν φεύγει.',
  'Lokale CVE-database': 'Τοπική βάση δεδομένων CVE',
  'Met de CVE-lijst op je eigen apparaat blijft het opzoeken hier: er gaat geen zoekterm meer naar een server, en niemand kan zien welk lek je onderzoekt.':
      'Με τη λίστα CVE στη δική σου συσκευή, οι αναζητήσεις μένουν εδώ: κανένας όρος αναζήτησης δεν πηγαίνει πια σε διακομιστή και κανείς δεν βλέπει ποια ευπάθεια ερευνάς.',
  'Uitpakken…': 'Γίνεται εξαγωγή…',
  'Zet de volledige CVE-lijst op dit apparaat, zodat opzoeken offline gebeurt en je zoekterm nergens heen gaat. De database komt van CVE List V5 (het officiële CVE-programma, via GitHub).':
      'Βάλε την πλήρη λίστα CVE σε αυτή τη συσκευή, ώστε οι αναζητήσεις να γίνονται εκτός σύνδεσης και ο όρος αναζήτησής σου να μην πηγαίνει πουθενά. Η βάση δεδομένων προέρχεται από το CVE List V5 (το επίσημο πρόγραμμα CVE, μέσω GitHub).',
  'Wat er lokaal beschikbaar is': 'Τι είναι διαθέσιμο τοπικά',
  'Nu bijwerken': 'Ενημέρωση τώρα',
  'Gegevens lokaal beschikbaar — het opzoeken gebeurt op dit apparaat, er gaat niets naar buiten.':
      'Τα δεδομένα είναι διαθέσιμα τοπικά — οι αναζητήσεις γίνονται σε αυτή τη συσκευή· τίποτα δεν φεύγει.',
  'Zwakheden (CWE)': 'Αδυναμίες (CWE)',
  'Testgevallen (WSTG)': 'Περιπτώσεις δοκιμών (WSTG)',
  'MIAUW-eisen': 'Απαιτήσεις MIAUW',
  'CVSS-scoretabel': 'Πίνακας βαθμολογίας CVSS',
  'Bevindingsjablonen': 'Πρότυπα ευρημάτων',
  'Zoek een instelling': 'Αναζήτηση ρύθμισης',
  'Geen instelling gevonden': 'Δεν βρέθηκε ρύθμιση',
  'Je zoekterm gaat naar de ingestelde CVE-mirror, en als die niets vindt ook naar ENISA en MITRE. Wie die servers beheert, kan daaruit afleiden naar welk specifiek lek je zoekt — en dus welk lek je onderzoekt.':
      'Ο όρος αναζήτησής σας πηγαίνει στο ρυθμισμένο κάτοπτρο CVE και, αν αυτό δεν βρει τίποτα, και στον ENISA και στη MITRE. Όποιος διαχειρίζεται αυτούς τους διακομιστές μπορεί να συμπεράνει ποια συγκεκριμένη ευπάθεια αναζητάτε — και άρα ποια ευπάθεια ερευνάτε.',
  'Accepteren': 'Αποδοχή',
  'Accepteren + waarschuwen': 'Αποδοχή + προειδοποίηση',
  'Accepteren: de gegevens horen hier en de melding verdwijnt. Accepteren + waarschuwen: de ontvanger ziet een badge dat er persoonsgegevens op de slide staan. Weglaten: de gevonden gegevens worden onleesbaar gemaakt op het scherm en in de export — je markdown-bestand houdt de oorspronkelijke tekst.':
      'Αποδοχή: τα δεδομένα ανήκουν εδώ και η ειδοποίηση εξαφανίζεται. Αποδοχή + προειδοποίηση: ο παραλήπτης βλέπει σήμα ότι η διαφάνεια περιέχει προσωπικά δεδομένα. Παράλειψη: τα δεδομένα που βρέθηκαν γίνονται δυσανάγνωστα στην οθόνη και στην εξαγωγή — το αρχείο Markdown σου κρατά το αρχικό κείμενο.',
  'Alleen melden': 'Μόνο αναφορά',
  'PERSOONSGEGEVENS': 'ΠΡΟΣΩΠΙΚΑ ΔΕΔΟΜΕΝΑ',
  'Volg de presentatie': 'Ακολούθησε την παρουσίαση',
  'Weglaten uit tonen en exporteren': 'Παράλειψη από προβολή και εξαγωγή',
  ' Overweeg dit te redigeren met [[dubbele blokhaken]].':
      ' Σκέψου να το αποκρύψεις με [[διπλές αγκύλες]].',
  ' Zonder context in de tekst is dit mogelijk geen persoonsgegeven.':
      ' Χωρίς συμφραζόμενα στο κείμενο, ίσως να μην είναι καν προσωπικό δεδομένο.',
  'Leest je dia\'s na op identificatienummers, contactgegevens en andere privacygevoelige gegevens, en meldt ze bij de kwaliteitscontrole. Dit gebeurt volledig op dit apparaat; er wordt niets verstuurd. Het is een hulpmiddel, geen garantie: tekst in afbeeldingen en gegevens zonder herkenbaar patroon blijven buiten beeld.':
      'Ελέγχει τις διαφάνειές σου για αριθμούς ταυτοποίησης, στοιχεία επικοινωνίας και άλλα ευαίσθητα δεδομένα, και τα αναφέρει στον έλεγχο ποιότητας. Γίνεται εξ ολοκλήρου σε αυτή τη συσκευή· δεν στέλνεται τίποτα. Είναι βοήθημα, όχι εγγύηση: κείμενο μέσα σε εικόνες και δεδομένα χωρίς αναγνωρίσιμο μοτίβο μένουν αόρατα.',
  'Mogelijk persoonsgegeven': 'Πιθανό προσωπικό δεδομένο',
  'Privacycontrole': 'Έλεγχος απορρήτου',
  'Waarschuw bij mogelijke persoonsgegevens':
      'Προειδοποίηση για πιθανά προσωπικά δεδομένα',
  'burgerservicenummer (BSN)': 'αριθμός μητρώου πολίτη (BSN)',
  'bankrekeningnummer (IBAN)': 'αριθμός τραπεζικού λογαριασμού (IBAN)',
  'e-mailadres': 'διεύθυνση email',
  'De TSA-handtekening is niet in-app geverifieerd; alleen de hash komt overeen.':
      'Η υπογραφή της TSA δεν επαληθεύεται στην εφαρμογή· ταιριάζει μόνο το hash.',
  'Extern': 'Εξωτερικό',
  'Van een externe URL opgehaald; het openen heeft die server benaderd.':
      'Λήφθηκε από εξωτερική διεύθυνση URL· το άνοιγμα επικοινώνησε με αυτόν τον διακομιστή.',
  'AI-assistentie (staat standaard uit): kies je een zelf-gehoste of cloud-backend, dan worden de teksten of afbeeldingen die je laat verwerken naar dat adres gestuurd. Wat je hebt geredigeerd, gaat er eerst uit. Een lokaal AI-model op dit apparaat verstuurt niets.':
      'Βοήθεια AI (ανενεργή από προεπιλογή): αν επιλέξεις self-hosted ή cloud backend, τα κείμενα ή οι εικόνες που δίνεις για επεξεργασία στέλνονται σε εκείνη τη διεύθυνση. Ό,τι έχεις αποκρύψει αφαιρείται πρώτα. Ένα τοπικό μοντέλο AI σε αυτή τη συσκευή δεν στέλνει τίποτα.',
  'Gegevens weglaten (redactie)': 'Παράλειψη δεδομένων (απόκρυψη)',
  'Zet je tekst tussen dubbele blokhaken, zoals [[het adres]], dan laat OciDeck die weg uit alles wat je toont en exporteert. Op de dia, in de presentatie, in de PDF, de PowerPoint en de HTML verschijnen alleen blokken.':
      'Βάλε κείμενο μέσα σε διπλές αγκύλες, όπως [[η διεύθυνση]], και το OciDeck το παραλείπει από όλα όσα δείχνεις και εξάγεις. Στη διαφάνεια, στην παρουσίαση, στο PDF, στο PowerPoint και στο HTML εμφανίζονται μόνο μπλοκ.',
  'Weggelaten is écht weggelaten, niet afgedekt. De tekst zit niet als onzichtbare laag onder een zwart balkje in de PDF, niet in de sprekersnotities van de PowerPoint, en niet in de broncode van de HTML. Wie het bestand openmaakt, kan er niets uit terughalen.':
      'Παραλειμμένο σημαίνει πραγματικά παραλειμμένο, όχι σκεπασμένο. Το κείμενο δεν βρίσκεται ως αόρατο στρώμα κάτω από μια μαύρη μπάρα στο PDF, ούτε στις σημειώσεις ομιλητή του PowerPoint, ούτε στον πηγαίο κώδικα του HTML. Όποιος ανοίξει το αρχείο δεν μπορεί να ανακτήσει τίποτα.',
  'Je eigen bestand verandert niet. De oorspronkelijke tekst blijft in je markdown staan; redactie geldt alleen voor wat je deelt. Zo houd je je eigen gegevens.':
      'Το δικό σου αρχείο δεν αλλάζει. Το αρχικό κείμενο παραμένει στο markdown σου· η απόκρυψη ισχύει μόνο για ό,τι μοιράζεσαι. Έτσι κρατάς τα δικά σου δεδομένα.',
  'map/presentatie': 'φάκελος/παρουσίαση',
  'Gekoppelde test': 'Συνδεδεμένος έλεγχος',
  'Maak eerst een checklist voor dit scope-object.':
      'Δημιούργησε πρώτα μια λίστα ελέγχου για αυτό το αντικείμενο εμβέλειας.',
  'Bewerken': 'Επεξεργασία',
  'Checklist-sjabloon': 'Πρότυπο λίστας ελέγχου',
  'Eigen checklists': 'Προσαρμοσμένες λίστες ελέγχου',
  'Laad een eigen checklist-sjabloon':
      'Φόρτωση προσαρμοσμένου προτύπου λίστας ελέγχου',
  'Leeg laten': 'Άφησε κενό',
  'Maak herbruikbare testlijsten die je per scope-object in een checklist kunt laden, naast de gebundelde WSTG-lijst.':
      'Δημιούργησε επαναχρησιμοποιήσιμες λίστες ελέγχων που μπορείς να φορτώσεις σε μια λίστα ελέγχου ανά αντικείμενο εμβέλειας, δίπλα στην ενσωματωμένη λίστα WSTG.',
  'Nieuw sjabloon': 'Νέο πρότυπο',
  'Nog geen eigen checklists.':
      'Δεν υπάρχουν ακόμη προσαρμοσμένες λίστες ελέγχου.',
  'Sjabloon laden…': 'Φόρτωση προτύπου…',
  'Sjabloon voor overige objecten': 'Πρότυπο για τα άλλα αντικείμενα',
  'Testen': 'Έλεγχοι',
  'Genereer checklists voor scope-objecten':
      'Δημιουργία λιστών ελέγχου για αντικείμενα εμβέλειας',
  'checklists toegevoegd': 'λίστες ελέγχου προστέθηκαν',
  'Alle scope-objecten hebben al een checklist':
      'Όλα τα αντικείμενα εμβέλειας έχουν ήδη λίστα ελέγχου',
  'Maakt per scope-object een checklist (WSTG voor web/API); bestaande blijven staan.':
      'Δημιουργεί μια λίστα ελέγχου ανά αντικείμενο εμβέλειας (WSTG για web/API)· οι υπάρχουσες διατηρούνται.',
  'CVE opzoeken': 'Αναζήτηση CVE',
  'CVE opzoeken (online)': 'Αναζήτηση CVE (διαδικτυακά)',
  'CVE opzoeken is niet beschikbaar in de webversie.':
      'Η αναζήτηση CVE δεν είναι διαθέσιμη στην έκδοση web.',
  'CVE-mirror (basis-URL)': 'Κάτοπτρο CVE (βασικό URL)',
  'Geen CVE gevonden.': 'Δεν βρέθηκε CVE.',
  'Kon de CVE-bron niet bereiken.': 'Δεν ήταν δυνατή η πρόσβαση στην πηγή CVE.',
  'Sta toe om in de bevinding-editor online in CVE\'s te zoeken via een NVD-mirror. Standaard uit; vereist ook je toestemming en werkt alleen op desktop.':
